```cpp
#include <iostream>
using namespace std;

class Zaman {
private:
    int saat, dakika, saniye;
    const int olusturmaSirasi;      // atanamaz, sadece ilklenebilir
    static int sayac;

    static int kirp(int v, int ust) { return (v < 0 ? 0 : (v > ust ? ust : v)); }

public:
    Zaman() : saat(0), dakika(0), saniye(0), olusturmaSirasi(++sayac) {}

    Zaman(int s, int d, int sn)
        : saat(kirp(s, 23)), dakika(kirp(d, 59)), saniye(kirp(sn, 59)),
          olusturmaSirasi(++sayac) {}

    void yaz() const {
        cout << "#" << olusturmaSirasi << " "
             << saat << ":" << dakika << ":" << saniye << endl;
    }
};

int Zaman::sayac = 0;

int main() {
    Zaman a;
    Zaman b(13, 45, 9);
    Zaman c(99, -5, 61);
    a.yaz();   // #1 0:0:0
    b.yaz();   // #2 13:45:9
    c.yaz();   // #3 23:0:59
    return 0;
}
```

Başlatma listesi zorunluluğu: `olusturmaSirasi` üyesi `const`tur. Kurucunun **gövdesine** girildiğinde tüm üyeler ilklenmiş sayılır, gövdede yapılan her şey atamadır; `const` bir nesneye atama yapılamaz, bu yüzden `olusturmaSirasi = ++sayac;` yazımı derlenmez. Aynı şey referans üyeler için de geçerlidir. Ayrıca `saat(kirp(s, 23))` yazımı ilkleme sırasında denetim yapar; gövdede düzeltseydik `saat` önce çöp/geçersiz bir değerle kurulup sonra düzeltilirdi — tek adımlı ilkleme hem daha doğru hem daha hızlıdır. `kirp` fonksiyonu nesneye ihtiyaç duymadığı için `static`tir ve bu sayede üyeler henüz ilklenmemişken, başlatma listesinin içinden güvenle çağrılabilir.

