```cpp
#include <iostream>
#include <string>
using namespace std;

class Urun {
    string ad;
    double fiyat;
    int stok;
    int kod;

    static int sonKod;
    static double toplamDeger;

public:
    Urun(const string &a, double f, int s)
        : ad(a), fiyat(f < 0 ? 0 : f), stok(s < 0 ? 0 : s), kod(++sonKod) {
        toplamDeger += fiyat * stok;
    }

    int    getKod()   const { return kod; }
    double getFiyat() const { return fiyat; }
    int    getStok()  const { return stok; }
    void yaz() const { cout << kod << " " << ad << " " << fiyat << " x" << stok << endl; }

    static double stokDegeri() { return toplamDeger; }

    friend class Depo;          // Depo fiyata dogrudan yazabilir
};

int    Urun::sonKod = 0;
double Urun::toplamDeger = 0.0;

class Depo {
public:
    static void indirimUygula(Urun &u, double yuzde) {
        Urun::toplamDeger -= u.fiyat * u.stok;     // private uyelere erisim
        u.fiyat = u.fiyat * (100 - yuzde) / 100;   // friend oldugu icin serbest
        Urun::toplamDeger += u.fiyat * u.stok;
    }
};

int main() {
    Urun a("klavye", 300, 2);
    Urun b("fare", 150, 4);
    a.yaz();                           // 1 klavye 300 x2
    b.yaz();                           // 2 fare 150 x4
    cout << Urun::stokDegeri() << endl;   // 1200
    Depo::indirimUygula(a, 50);
    a.yaz();                           // 1 klavye 150 x2
    cout << Urun::stokDegeri() << endl;   // 900
    return 0;
}
```

Gerekçeler: **`static`** seçildi çünkü 'son verilen kod' ve 'toplam stok değeri' tek bir ürüne ait bilgiler değil, tüm `Urun` kümesine ait bilgilerdir; her nesnede kopyasını tutmak hem yer israfı hem de tutarsızlık kaynağı olurdu. `stokDegeri()` de nesne gerektirmediği için `static`tir. **`const`** seçildi çünkü `getFiyat`, `getStok`, `getKod` ve `yaz` nesneyi değiştirmez; bu söz sayesinde `const Urun&` parametresi alan raporlama fonksiyonları onları çağırabilir. **`friend`** seçildi çünkü `Depo`, indirim uygularken hem `fiyat`ı değiştirmek hem de statik `toplamDeger`i tutarlı tutmak zorunda; bu iki işin **atomik** olması gerekiyor. `setFiyat` diye `public` bir fonksiyon koysaydık herkes fiyatı değiştirebilir ve `toplamDeger` güncellenmeden bozulurdu. Yine de `friend` en son seçenektir: burada alternatif olarak `Urun` içine `public bool indirimUygula(double)` yazmak da kabul edilebilir, hatta daha temiz bir tasarımdır.

