#include <iostream>
using namespace std;

class Dizi {
    int *d;
    int n;
public:
    Dizi(int boyut) : d(new int[boyut]), n(boyut) {
        for (int i = 0; i < n; i++) d[i] = 0;
    }
    Dizi(const Dizi &o) : d(new int[o.n]), n(o.n) {
        for (int i = 0; i < n; i++) d[i] = o.d[i];
    }
    Dizi& operator=(const Dizi &o) {
        if (this != &o) {
            delete[] d;
            n = o.n;
            d = new int[n];
            for (int i = 0; i < n; i++) d[i] = o.d[i];
        }
        return *this;
    }
    ~Dizi() { delete[] d; }

    int&       operator[](int i)       { return d[i]; }
    const int& operator[](int i) const { return d[i]; }

    friend ostream& operator<<(ostream &os, const Dizi &a) {
        for (int i = 0; i < a.n; i++) {
            if (i > 0) os << " ";
            os << a.d[i];
        }
        return os;
    }
};

