```cpp
#include <iostream>
using namespace std;

class Kesir {
    long pay, payda;

    static long ebob(long a, long b) {
        if (a < 0) a = -a;
        if (b < 0) b = -b;
        while (b != 0) { long t = a % b; a = b; b = t; }
        return (a == 0 ? 1 : a);
    }
    void sadelestir() {
        if (payda == 0) { pay = 0; payda = 1; return; }
        if (payda < 0) { pay = -pay; payda = -payda; }
        long g = ebob(pay, payda);
        pay /= g;
        payda /= g;
    }

public:
    Kesir(long p = 0, long q = 1) : pay(p), payda(q) { sadelestir(); }

    Kesir operator+(const Kesir &o) const {
        return Kesir(pay * o.payda + o.pay * payda, payda * o.payda);
    }
    Kesir operator*(const Kesir &o) const {
        return Kesir(pay * o.pay, payda * o.payda);
    }
    bool operator==(const Kesir &o) const { return pay == o.pay && payda == o.payda; }
    bool operator!=(const Kesir &o) const { return !(*this == o); }
    bool operator<(const Kesir &o) const { return pay * o.payda < o.pay * payda; }

    friend ostream& operator<<(ostream &os, const Kesir &k) {
        if (k.payda == 1) os << k.pay;
        else os << k.pay << "/" << k.payda;
        return os;
    }
};

int main() {
    Kesir a(1, 2), b(1, 3), c(2, 4);
    cout << a + b << endl;        // 5/6
    cout << a * b << endl;        // 1/6
    cout << boolalpha;
    cout << (a == c) << endl;     // true  (2/4 -> 1/2)
    cout << (b < a) << endl;      // true  (1*2 < 1*3)
    cout << a + a << endl;        // 1     (2/2 sadelesti)
    cout << a << endl;            // 1/2   (a BOZULMADI)
    return 0;
}
```

`+` operatörünün **değerle döndürülmesi** ve **`const` üye** olması iki sebeple zorunludur. Birincisi anlamsaldır: `c = a + b;` yazan programcı `a` ve `b`nin olduğu gibi kalmasını bekler; toplamı `*this`e yazıp `*this` döndürmek `+`ı gizli bir `+=`a çevirir ve `a + b + c` gibi ifadelerde birikmeli bozulma üretir. İkincisi teknik: sonuç **yeni bir değerdir**, bellekte hâlihazırda bir yeri yoktur; referans döndürmek ya yerel bir geçiciye referans vermek (sarkan referans, tanımsız davranış) ya da mevcut nesneyi değiştirmek anlamına gelir. `const` üye olması ise `const Kesir` nesneleri ve `const Kesir&` parametreleri üzerinde de toplama yapılabilmesini sağlar. Ek not: `+`ı `friend Kesir operator+(const Kesir&, const Kesir&)` biçiminde serbest yazsaydık `2 + a` gibi ifadeler de (sol işlenen örtük dönüşümle) çalışırdı; üye sürümde yalnızca `a + 2` çalışır.

