```cpp
#include <iostream>
#include <string>
using namespace std;

class Calisan {
private:
    string ad;
    double maas;
protected:
    double getMaas() const { return maas; }       // turemisler icin denetimli kapi
    void setMaas(double m) { if (m >= 0) maas = m; }
public:
    Calisan(const string &a, double m) : ad(a), maas(m < 0 ? 0 : m) {
        cout << "Calisan kurucu: " << ad << endl;
    }
    ~Calisan() { cout << "Calisan yikici: " << ad << endl; }

    string getAd() const { return ad; }
    double odenecek() const { return maas; }
    void yaz() const { cout << ad << " -> " << odenecek() << endl; }
};

class Muhendis : public Calisan {
    string alan;
public:
    Muhendis(const string &a, double m, const string &al)
        : Calisan(a, m), alan(al) { cout << "Muhendis kurucu" << endl; }
    ~Muhendis() { cout << "Muhendis yikici" << endl; }
    double odenecek() const { return getMaas() * 1.10; }   // %10 teknik tazminat
    void yaz() const { cout << getAd() << " [" << alan << "] -> " << odenecek() << endl; }
};

class Yonetici : public Calisan {
    int kisiSayisi;
    double primOrani;
public:
    Yonetici(const string &a, double m, int k, double p)
        : Calisan(a, m), kisiSayisi(k), primOrani(p) { cout << "Yonetici kurucu" << endl; }
    ~Yonetici() { cout << "Yonetici yikici" << endl; }
    double odenecek() const { return getMaas() * (1 + primOrani) + kisiSayisi * 100; }
    void yaz() const { cout << getAd() << " (" << kisiSayisi << " kisi) -> " << odenecek() << endl; }
};

int main() {
    Muhendis m("Ayse", 30000, "gomulu");
    m.yaz();                 // Ayse [gomulu] -> 33000

    Calisan *p = &m;
    p->yaz();                // Ayse -> 30000   <-- SORUN!
    return 0;
}
```

Çıktı sırası `Calisan kurucu: Ayse`, `Muhendis kurucu`, sonra yazdırmalar, en sonda `Muhendis yikici`, `Calisan yikici: Ayse` olur — temel önce kurulur, en son yıkılır.

**Erişim seçimleri:** `ad` ve `maas` `private`tır, çünkü doğrudan yazılabilir olsalar negatif maaş gibi geçersiz durumlar oluşur ve iç temsili (örneğin maaşı kuruş cinsinden `long` tutmaya geçmek) değiştirmek tüm türemiş sınıfları bozar. Türemişlerin maaşa ihtiyacı olduğu için veri yerine **`protected` fonksiyon** (`getMaas`, `setMaas`) verildi: denetim korunur, iç temsil serbest kalır. `odenecek`, `yaz` ve `getAd` `public`tır çünkü dışarının kullandığı arayüzdür. Kalıtım `public`tır, çünkü gerçekten 'her mühendis bir çalışandır'.

**`virtual` olmamasının sorunu:** `Calisan *p = &m; p->yaz();` çağrısı, `yaz` sanal olmadığı için **statik tipe** göre bağlanır ve `Calisan::yaz`ı çalıştırır; ekranda tazminatsız 30000 görünür. Aynı şekilde `odenecek` de temel sürümden çağrılır. Yani farklı çalışan türlerini `Calisan*` dizisinde toplayıp bordro hesaplamak **imkânsızdır**. Çözüm, `odenecek` ve `yaz` fonksiyonlarını `virtual` yapmak (ve `Calisan`a sanal yıkıcı eklemek) — bu da 9. haftanın konusudur.

