```cpp
#include <iostream>
#include <string>
using namespace std;

// --- ortak DURUM (veri tasir) ---
class Cihaz {
protected:
    string marka;
    int seriNo;
    bool acik;
public:
    Cihaz(const string &m = "?", int s = 0) : marka(m), seriNo(s), acik(false) {
        cout << "Cihaz(" << marka << "," << seriNo << ")" << endl;
    }
    virtual ~Cihaz() { cout << "~Cihaz" << endl; }
    void ac()  { acik = true;  }
    void kapat() { acik = false; }
    bool acikMi() const { return acik; }
    string kimlik() const { return marka + "#" + to_string(seriNo); }
};

// --- ARAYUZLER (veri YOK) ---
class IYazici {
public:
    virtual void yazdir(const string &belge) = 0;
    virtual ~IYazici() {}
};
class ITarayici {
public:
    virtual string tara() = 0;
    virtual ~ITarayici() {}
};
class IFaks {
public:
    virtual void faksGonder(const string &no, const string &belge) = 0;
    virtual ~IFaks() {}
};

// --- ara gerceklestirmeler: Cihaz'i SANAL devralir ---
class Yazici : virtual public Cihaz, public IYazici {
public:
    Yazici() { cout << "Yazici" << endl; }
    void yazdir(const string &belge) override {
        if (!acikMi()) { cout << kimlik() << ": kapali" << endl; return; }
        cout << kimlik() << " yazdiriyor: " << belge << endl;
    }
};

class Tarayici : virtual public Cihaz, public ITarayici {
public:
    Tarayici() { cout << "Tarayici" << endl; }
    string tara() override { return kimlik() + "-tarama.png"; }
};

class CokFonksiyonluCihaz : public Yazici, public Tarayici, public IFaks {
public:
    CokFonksiyonluCihaz(const string &m, int s)
        : Cihaz(m, s) { cout << "CokFonksiyonluCihaz" << endl; }   // sanal tabani EN TUREMIS ilkler
    void faksGonder(const string &no, const string &belge) override {
        cout << kimlik() << " -> " << no << " faks: " << belge << endl;
    }
    void kopyala() { yazdir(tara()); }   // iki yetenegi birlestirir
};

int main() {
    CokFonksiyonluCihaz c("Kirikkale", 2003);
    c.ac();
    c.kopyala();
    c.faksGonder("0318...", "dilekce.pdf");

    IYazici *y = &c;
    y->yazdir("tek-sayfa.txt");
    return 0;
}
```

Kuruluş sırası şöyle olur: sanal taban `Cihaz` **en başta ve bir kez** (`Cihaz(Kirikkale,2003)`), sonra bildirim sırasıyla `Yazici`, `Tarayici`, en sonda `CokFonksiyonluCihaz`. Yıkım tam tersidir.

**Sanal kalıtım neden gerekli:** `Yazici` ve `Tarayici` ikisi de `Cihaz`dan türüyor; `CokFonksiyonluCihaz` ikisinden birden türediği için klasik elmas oluşur. `virtual` yazmazsak cihazın **iki marka, iki seri no ve iki `acik` bayrağı** olur. Somut sonuçlar: (1) `c.ac()` yalnızca bir kopyayı açar, `Tarayici` tarafı kendini kapalı sanar — yani nesne kendi içinde tutarsız hâle gelir; (2) `acikMi()` veya `kimlik()` çağrısı 'ambiguous' hatası verir, her yerde `Yazici::kimlik()` diye nitelemek gerekir; (3) `Cihaz *p = &c;` dönüşümü belirsiz olduğu için derlenmez; (4) `Cihaz` kurucusu iki kez çalışır, kaynak açıyorsa iki kez açılır. `virtual public Cihaz` yazıldığında tek bir paylaşılan `Cihaz` kalır ve bu sorunların tamamı ortadan kaybolur; bedeli nesnenin bir miktar büyümesi ve taban üyelerine erişimin bir dolaylılık eklemesidir.

**Arayüz çoklu kalıtımı neden güvenli:** `IYazici`, `ITarayici`, `IFaks` hiç veri üyesi tutmaz; yalnızca saf sanal fonksiyon ve sanal yıkıcı içerirler. Paylaşılacak durum olmadığı için 'iki kopya' sorunu doğmaz, bu yüzden onları `virtual` devralmaya gerek yoktur. Kalan tek risk isim çakışmasıdır (iki arayüzde aynı imzalı farklı anlamda fonksiyon olması) ve o da nitelemeyle çözülür. Altın kural: **durum için sanal kalıtım veya kompozisyon, davranış için arayüz çoklu kalıtımı.**

