```cpp
#include <iostream>
#include <cstring>
#include <string>
using namespace std;

template <typename T, int KAPASITE = 8>
class Yigin {
    T d[KAPASITE];
    int tepe;                 // -1 = bos
public:
    Yigin() : tepe(-1) {}

    bool bosMu()  const { return tepe < 0; }
    bool doluMu() const { return tepe == KAPASITE - 1; }
    int  boyut()  const { return tepe + 1; }
    int  kapasite() const { return KAPASITE; }

    bool it(const T &v) {                 // push
        if (doluMu()) return false;
        d[++tepe] = v;
        return true;
    }
    bool cek(T &hedef) {                  // pop
        if (bosMu()) return false;
        hedef = d[tepe--];
        return true;
    }
    const T& tepedekiniGor() const { return d[tepe]; }
};

template <typename T>
T enBuyuk(T a, T b) { return (a > b) ? a : b; }

template <>
const char* enBuyuk<const char *>(const char *a, const char *b) {
    return (strcmp(a, b) > 0) ? a : b;     // SOZLUK sirasina gore
}

int main() {
    Yigin<int, 3> y;
    cout << y.it(10);                                               // 1
    cout << y.it(20);                                               // 1
    cout << y.it(30);                                               // 1
    cout << y.it(40) << endl;                                       // 0 -> kapasite doldu
    cout << y.boyut() << " " << y.tepedekiniGor() << endl;          // 3 30

    int v;
    while (y.cek(v)) cout << v << " ";
    cout << "| bos mu: " << y.bosMu() << endl;                      // 30 20 10 | bos mu: 1

    Yigin<string, 2> s;
    s.it("ali");
    s.it("veli");
    string t;
    s.cek(t);
    cout << t << " " << s.boyut() << endl;                          // veli 1

    cout << enBuyuk(3, 7) << " " << enBuyuk(2.5, 1.5) << endl;      // 7 2.5
    cout << enBuyuk<const char *>("elma", "armut") << endl;         // elma
    return 0;
}
```

Tek bir `Yigin` tanımı hem `int` hem `string` için çalışıyor; `string` sürümü için derleyici ayrı kod üretir ve `d[++tepe] = v;` satırı orada `string::operator=`ı çağırır. `const char*` uzmanlaştırması olmasaydı `enBuyuk("elma", "armut")` iki **adresi** karşılaştırır ve sonuç rastgele olurdu.

**Şablon (derleme anı çok biçimliliği) ile sanal fonksiyon (çalışma anı çok biçimliliği) karşılaştırması:**

| Ölçüt | Şablon | Sanal fonksiyon |
|---|---|---|
| Karar zamanı | Derleme anı | Çalışma anı |
| Maliyet | Sıfır çalışma anı maliyeti, kod şişmesi | vptr (nesne başına 8 bayt) + bir dolaylılık |
| Satır içi alma | Mümkün, çok hızlı | Genelde mümkün değil |
| Tip ilişkisi | Gerekmez; `int` de `string` de olur | Ortak temel sınıf **şart** |
| Çalışma anında tip seçimi | Mümkün değil | Mümkün (dosyadan okunan tipe göre nesne üretmek) |
| Hata mesajları | Uzun ve şablonun içinden | Kısa ve net |
| Heterojen kapsayıcı | Yapılamaz (`Yigin<int>` yalnızca int tutar) | Yapılabilir (`Sekil*` dizisi) |

Pratikte ikisi birbirinin alternatifi değil tamamlayıcısıdır: STL kapsayıcıları şablonla, şekil/cihaz hiyerarşileri sanal fonksiyonla yazılır. 'Aynı algoritma farklı tiplerde' ise şablon, 'aynı arayüz farklı davranışlarda ve tip çalışma anında belirleniyor' ise sanal fonksiyon doğru araçtır.

