        cout << ++n << ":" << satir << endl;
    }
    cout << "eof=" << g.eof() << " fail=" << g.fail() << endl;

    int x;
    ifstream h("log.txt");
    cout << "okundu mu=" << static_cast<bool>(h >> x) << endl;
    return 0;
}

