```cpp
#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <memory>
using namespace std;

// ---------- MODEL: yalnizca sekil olmayi bilir ----------
class Sekil {
public:
    virtual ~Sekil() {}
    virtual string tip() const = 0;              // tip ETIKETI
    virtual double alan() const = 0;
    virtual void alanlariYaz(ostream &os) const = 0;   // kendi alanlari
    virtual void alanlariOku(istream &is) = 0;
};

class Dikdortgen : public Sekil {
    double en, boy;
public:
    Dikdortgen(double e = 0, double b = 0) : en(e), boy(b) {}
    string tip() const override { return "DIK"; }
    double alan() const override { return en * boy; }
    void alanlariYaz(ostream &os) const override { os << en << ' ' << boy; }
    void alanlariOku(istream &is) override { is >> en >> boy; }
};

class Daire : public Sekil {
    double r;
public:
    Daire(double yaricap = 0) : r(yaricap) {}
    string tip() const override { return "DAI"; }
    double alan() const override { return 3.14159265 * r * r; }
    void alanlariYaz(ostream &os) const override { os << r; }
    void alanlariOku(istream &is) override { is >> r; }
};

class Kare : public Sekil {
    double k;
public:
    Kare(double kenar = 0) : k(kenar) {}
    string tip() const override { return "KAR"; }
    double alan() const override { return k * k; }
    void alanlariYaz(ostream &os) const override { os << k; }
    void alanlariOku(istream &is) override { is >> k; }
};

// ---------- SERILESTIRME: modelden AYRI ----------
ostream& operator<<(ostream &os, const Sekil &s) {
    os << s.tip() << ' ';
    s.alanlariYaz(os);
    return os;
}

// FABRIKA: etikete gore dogru turden nesne uretir
unique_ptr<Sekil> sekilUret(const string &etiket) {
    if (etiket == "DIK") return unique_ptr<Sekil>(new Dikdortgen());
    if (etiket == "DAI") return unique_ptr<Sekil>(new Daire());
    if (etiket == "KAR") return unique_ptr<Sekil>(new Kare());
    return nullptr;
}

unique_ptr<Sekil> sekilOku(istream &is) {
    string etiket;
    if (!(is >> etiket)) return nullptr;
    unique_ptr<Sekil> s = sekilUret(etiket);
    if (!s) return nullptr;
    s->alanlariOku(is);
    return s;
}

// ---------- KAYDEDICI SOYUTLAMASI (Dependency Inversion) ----------
class Kaydedici {
public:
    virtual ~Kaydedici() {}
    virtual void kaydet(const vector<unique_ptr<Sekil> > &liste) = 0;
};

class DosyaKaydedici : public Kaydedici {
    string ad;
public:
    explicit DosyaKaydedici(const string &dosya) : ad(dosya) {}
    void kaydet(const vector<unique_ptr<Sekil> > &liste) override {
        ofstream f(ad.c_str());
        for (size_t i = 0; i < liste.size(); i++) f << *liste[i] << "\n";
    }
};

class EkranKaydedici : public Kaydedici {
public:
    void kaydet(const vector<unique_ptr<Sekil> > &liste) override {
        for (size_t i = 0; i < liste.size(); i++) cout << *liste[i] << endl;
    }
};

int main() {
    vector<unique_ptr<Sekil> > liste;
    liste.push_back(unique_ptr<Sekil>(new Dikdortgen(3, 4)));
    liste.push_back(unique_ptr<Sekil>(new Daire(2)));
    liste.push_back(unique_ptr<Sekil>(new Kare(5)));

    EkranKaydedici ekran;
    ekran.kaydet(liste);          // DIK 3 4 / DAI 2 / KAR 5

    DosyaKaydedici dosya("sekiller.txt");
    dosya.kaydet(liste);

    // geri yukle
    ifstream g("sekiller.txt");
    vector<unique_ptr<Sekil> > geri;
    while (unique_ptr<Sekil> s = sekilOku(g)) geri.push_back(move(s));

    double toplam = 0;
    for (size_t i = 0; i < geri.size(); i++) toplam += geri[i]->alan();
    cout << geri.size() << " sekil, toplam alan = " << toplam << endl;
    // 3 sekil, toplam alan = 49.5664
    return 0;
}
```

Dosya içeriği şöyle olur:

```
DIK 3 4
DAI 2
KAR 5
```

**Neden tip etiketi zorunlu:** dosyadan okurken elinizde yalnızca baytlar vardır; hangi sınıftan nesne üretileceğini dosyanın kendisi söylemelidir. Bu yüzden her satır tipini taşır ve `sekilUret` fabrikası etiketten nesne üretir. Bu, çok biçimli serileştirmenin değişmez kuralıdır — `new Sekil()` yazmak mümkün değildir (soyut sınıf), somut tipi bilen biri gerekir.

**SOLID açısından kazançlar:**

- **Tek sorumluluk (S):** `Dikdortgen` yalnızca geometrisini ve kendi alanlarını nasıl yazacağını bilir; dosya adı, açma kipi, satır sonu biçimi gibi hiçbir ayrıntıyı bilmez. Dosya biçimi değişirse şekil sınıfları değişmez, `DosyaKaydedici` değişir.
- **Açık-kapalı (O):** Yeni bir `Ucgen` eklemek için `operator<<`, `Kaydedici` sınıfları veya toplam alan döngüsü **hiç değişmez**; yeni sınıf yazılır ve `sekilUret`e bir satır eklenir. (Fabrikanın o tek `if` zinciri ilkenin pratik sınırıdır; kayıt tablosu — `map<string, üretici fonksiyon>` — ile o da kapatılabilir.)
- **Bağımlılığın tersine çevrilmesi (D):** Üst seviye kod `Kaydedici` **soyutlamasına** bağımlıdır, `ofstream`a değil. Bu sayede aynı kod ekrana, dosyaya, ağa veya testte belleğe yazabilir; birim testi için `SahteKaydedici` yazmak yeterlidir. `Sekil` içine `dosyayaYaz(const char*)` koymuş olsaydık bu esnekliğin tamamı kaybolurdu.
- **Arayüz ayrıştırma (I):** `Sekil` yalnızca şekil olmaya dair fonksiyonları zorunlu kılar; 'veritabanına yaz', 'ekranda çiz', 'JSON üret' gibi işler ayrı arayüzlere bırakılır, böylece yeni bir şekil yazmak için onlarca ilgisiz fonksiyonu gerçekleştirmeniz gerekmez.
- **Liskov (L):** Her türemiş sınıf `alan()` sözünü aynı anlamda yerine getirir (negatif olmayan bir alan döndürür) ve `alanlariYaz`/`alanlariOku` çifti simetriktir; bu yüzden hiçbir `Sekil*` kullanıcısı gerçek tipe göre özel durum yazmak zorunda kalmaz.
